def max_result(nums, k):
    n = len(nums)
    dp = [float('-inf')] * n
    dp[0] = nums[0]
    for i in range(1, n):
        for j in range(max(0, i - k), i):                                  # rescan up to k previous positions every single step
            dp[i] = max(dp[i], dp[j] + nums[i])
    return dp[n - 1]


if __name__ == "__main__":
    print(max_result([1, -1, -2, 4, -7, 3], 2))

