import java.util.*;

public class Main {
    int maxResult(int[] nums, int k) {
        int n = nums.length;
        int[] dp = new int[n];
        dp[0] = nums[0];
        Deque<Integer> window = new ArrayDeque<>();                                  // monotonic DECREASING deque of indices, by dp value
        window.addLast(0);

        for (int i = 1; i < n; i++) {
            while (!window.isEmpty() && window.peekFirst() < i - k) {                   // evict indices that have fallen OUT of the k-window
                window.pollFirst();
            }
            dp[i] = dp[window.peekFirst()] + nums[i];                                   // the deque's front holds the best reachable score so far
            while (!window.isEmpty() && dp[window.peekLast()] <= dp[i]) {               // maintain decreasing order: pop anything dp[i] now dominates
                window.pollLast();
            }
            window.addLast(i);
        }

        return dp[n - 1];
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] nums = {1, -1, -2, 4, -7, 3};
        System.out.println(solution.maxResult(nums, 2));
    }
}

