#include <bits/stdc++.h>
using namespace std;

int maxResult(vector<int>& nums, int k) {
    int n = nums.size();
    vector<int> dp(n);
    dp[0] = nums[0];
    deque<int> window;                                                                    // monotonic DECREASING deque of indices, by dp value
    window.push_back(0);

    for (int i = 1; i < n; i++) {
        while (!window.empty() && window.front() < i - k) {                                   // evict indices that have fallen OUT of the k-window
            window.pop_front();
        }
        dp[i] = dp[window.front()] + nums[i];                                                  // the deque's front holds the best reachable score so far
        while (!window.empty() && dp[window.back()] <= dp[i]) {                                // maintain decreasing order: pop anything dp[i] now dominates
            window.pop_back();
        }
        window.push_back(i);
    }

    return dp[n - 1];
}

int main() {
    vector<int> nums = {1, -1, -2, 4, -7, 3};
    cout << maxResult(nums, 2) << endl;
